// Function 노드의 코드

// 입력된 snippet 데이터 가져오기
const snippet = $('Gmail Trigger').first().json.snippet


// 필요한 정보 추출을 위한 정규표현식 패턴 정의
// 기존: const codePattern = /코드를 입력하십시오\.\s*(\d+)\s*코드는/;
// 변경: 6자리 숫자만 추출
const codePattern = /\b(\d{6})\b/;
const datePattern = /Date\s+([\d\/:\sAPM]+)/;
const browserPattern = /Browser\s+([^\n]+)/;
const osPattern = /Operating System\s+([^\n]+)/;
const locationPattern = /Location\s+([^\n]+)/;
const namePattern = /안녕하세요([^\s,]+)[님,|,\n]/;

// 각 정보 추출
const codeMatch = snippet.match(codePattern);
const dateMatch = snippet.match(datePattern);
const browserMatch = snippet.match(browserPattern);
const osMatch = snippet.match(osPattern);
const locationMatch = snippet.match(locationPattern);
const nameMatch = snippet.match(namePattern);

// 추출된 데이터 변수에 저장
const code = codeMatch ? codeMatch[1] : '';
const date = dateMatch ? dateMatch[1] : '';
const browser = browserMatch ? browserMatch[1] : '';
const os = osMatch ? osMatch[1] : '';
const location = locationMatch ? locationMatch[1] : '';
const name = nameMatch ? nameMatch[1] : '고객';

// 이미지 URL 수정 (실제 이미지 URL 사용)
const imageUrl = 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRohD4e3zXSpC1mpURiV_opXy6Av6SY06v49g&s';

// HTML 템플릿 작성
const htmlContent = `
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Zoom 보안 알림</title>
    <style type="text/css">
        body { font-family: '맑은 고딕', Arial, sans-serif; background-color: #EEEEEE; margin: 0; padding: 0; }
        .container { max-width: 600px; margin: 0 auto; background-color: #FFFFFF; padding: 40px; }
        .header { padding: 20px; text-align: center; }
        .header img { max-width: 100px; }
        .content { margin-top: 40px; font-size: 14px; color: #232333; line-height: 1.5; }
        .content h1 { font-size: 24px; }
        .code { font-size: 28px; font-weight: bold; letter-spacing: 0.2em; margin: 20px 0; }
        .details { background-color: #F7F7FC; padding: 20px; }
        .details table { width: 100%; }
        .details td { padding: 5px 0; }
        .details td.label { color: #747487; width: 30%; }
        .footer { margin-top: 40px; font-size: 12px; color: #747487; }
        .footer a { color: #0E71EB; text-decoration: none; }
    </style>
</head>
<body>
    <div class="header">
        <img src="${imageUrl}" alt="Zoom Logo" style="display:block; font-family:'Lato',Helvetica,sans-serif; font-size:18px; line-height:22px; color:#76798a; font-weight:bold; width:100%; max-width:100px" width="100">
    </div>
    <div class="container">
        <div class="content">
            <p>안녕하세요 ${name},</p>
            <p>평소에 사용하지 않는 장치 또는 위치에서 비정상적인 로그인이 감지되었습니다. 귀하가 맞으면 Zoom에 로그인하기 위해 아래에 코드를 입력하십시오.</p>
            <div class="code">${code}</div>
            <p>코드는 10분 후 만료됩니다.</p>
            <p>아래 로그인 활동 세부 정보를 검토하십시오.</p>
            <div class="details">
                <table>
                    <tr>
                        <td class="label">Date</td>
                        <td>${date}</td>
                    </tr>
                    <tr>
                        <td class="label">Browser</td>
                        <td>${browser}</td>
                    </tr>
                    <tr>
                        <td class="label">Operating System</td>
                        <td>${os}</td>
                    </tr>
                    <tr>
                        <td class="label">Location</td>
                        <td>${location}</td>
                    </tr>
                </table>
            </div>
            <p>만약 귀하가 아니라면, <a href="https://zoom.us/security">여기</a>에서 저희에게 알려주십시오. 계정 보안을 위해 암호를 업데이트하고 2단계 인증을 사용하는 것이 좋습니다.</p>
            <p>감사합니다.<br>Zoom 운영팀</p>
        </div>
        <div class="footer">
            <p>계정의 보안을 강화하기 위해 로그인 경고를 활성화했습니다. 새로운 브라우저, 위치 또는 장치에서 로그인 활동이 감지되면 사용자에게 알려드립니다.</p>
        </div>
    </div>
</body>
</html>
`;

// 결과를 json으로 반환
return [{ json: { htmlContent, code } }];
